pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: address for Alice
        address alice = address(0x123);
        // Fund Alice with 200 wei
        vm.deal(alice, 200);

        // Alice deposits 200 wei (calls Deposit via receive)
        vm.prank(alice);
        (bool depositOk,) = address(c).call{value: 200}("");
        require(depositOk, "deposit failed");

        // Set MinSum to 50
        c.SetMinSum(50);
        // Initialize contract (so SetMinSum can't be called again)
        c.Initialized();

        // Alice calls Collect(200)
        vm.prank(alice);
        c.Collect(200);

        // After reference, balance becomes 0; after bug, it becomes 200 + 200 = 400
        assertTrue(c.balances(alice) == 0);
    }
}

