pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up initial state
        address alice = address(0x1);
        address bob = address(0x2);

        // Alice deposits 100 wei
        vm.deal(alice, 100 wei);
        vm.prank(alice);
        c.Deposit{value: 100 wei}();

        // Set MinSum to 50
        c.SetMinSum(50);

        // Initialize
        c.Initialized();

        // Bob deposits 10 wei (less than MinSum, but enough for Collect(10) since condition checks balances[msg.sender] >= MinSum (false) and balances >= _am (10 >= 10 true))
        vm.deal(bob, 10 wei);
        vm.prank(bob);
        c.Deposit{value: 10 wei}();

        // Bob calls Collect(10) — this will fail because balances[Bob] = 10 < MinSum = 50; condition fails, so no state change
        // But we want a condition that passes on reference: we need Bob to have at least MinSum
        // Let's adjust: Bob deposits more
        vm.deal(bob, 50 wei);
        vm.prank(bob);
        c.Deposit{value: 50 wei}();

        // Now Bob has 60 wei (10 + 50)
        // Bob calls Collect(60)
        vm.prank(bob);
        c.Collect(60);

        // Assert: reference reduces Bob's balance to 0, bug increases to 120
        assertTrue(c.balances(bob) == 0);
    }
}

