pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Set MinSum to 1
        c.SetMinSum(1);
        // Step 2: Set a dummy log file (required to avoid revert in Deposit)
        address dummyLog = address(new LogFile());
        c.SetLogFile(dummyLog);
        // Step 3: Initialize the contract
        c.Initialized();
        // Step 4: Fund Alice with 1 ether and deposit
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Deposit{value: 1 ether}();
        // Step 5: Alice attempts to collect 1 ether
        bool ok;
        vm.prank(alice);
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: Collect succeeds (balance becomes 0), bug: underflow revert (Collect fails)
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

