contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the contract: initialize, set MinSum, and set LogFile
        c.SetMinSum(1 ether);
        c.SetLogFile(address(0xdead)); // dummy, but required to avoid revert
        c.Initialized();

        // Actor deposits 1 ether
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Deposit{value: 1 ether}();

        // Actor can collect since balance >= MinSum (1 ether >= 1 ether)
        vm.prank(actor);
        c.Collect(1 ether);

        // Assert: Log.History.length should be 2 (Deposit + Collect) in reference, but buggy removes Deposit log, so length becomes 1
        assertTrue(c.LogFile(address(c.Log)).History.length == 2, "History length should be 2");
    }
}

