pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up initial conditions
        c.SetMinSum(10);
        c.SetLogFile(address(0x123));
        c.Initialized();

        address alice = address(0xAAAA);
        address bob = address(0xBBBB);

        // Alice deposits 10 wei
        vm.deal(alice, 10);
        vm.prank(alice);
        c.Deposit{value: 10}();

        // Bob deposits 10 wei (balance exactly MinSum)
        vm.deal(bob, 10);
        vm.prank(bob);
        c.Deposit{value: 10}();

        // Bob tries to collect 10 wei
        vm.prank(bob);
        // For the reference contract this succeeds, for the buggy it reverts
        bool ok;
        try c.Collect(10) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: reference succeeds (ok == true), buggy reverts (ok == false)
        // We assert reference behavior; the failing test on buggy will show divergence.
        assertTrue(ok == true);
    }
}

